<section class="card staff-detail-card"><div class="staff-section-title"><i data-lucide="sparkles"></i><div><h3>Skills & internal notes</h3></div></div><?php if($record['skills']):?><div class="staff-skills"><?php foreach(array_filter(array_map('trim',explode(',',$record['skills']))) as $skill):?><span><?=htmlspecialchars($skill)?></span><?php endforeach?></div><?php else:?><p class="staff-muted">No skills have been added.</p><?php endif?><h4>Internal notes</h4><p><?=nl2br(htmlspecialchars($record['internal_notes']?:'No internal notes.'))?></p></section>
