<section class="card staff-detail-card"><div class="staff-section-title"><i data-lucide="chart-no-axes-combined"></i><div><h3>Card analytics</h3></div></div><div class="staff-analytics-grid"><div><strong><?=number_format((int)$record['total_views'])?></strong><span>Total views</span></div><div><strong><?=number_format((int)$record['unique_views'])?></strong><span>Unique views</span></div><div><strong><?=number_format((int)$record['qr_scans'])?></strong><span>QR scans</span></div><div><strong><?=number_format((int)($analytics['save_contact']??0))?></strong><span>Contacts saved</span></div><div><strong><?=number_format((int)($analytics['call']??0))?></strong><span>Calls</span></div><div><strong><?=number_format((int)($analytics['whatsapp']??0))?></strong><span>WhatsApp</span></div></div></section>
